mapper.select:
SELECT 
  FROM tdm10_task
       INNER JOIN tdm14_task_type ON tdm10_company_id = tdm14_company_id AND tdm14_task_type_cd = tdm10_task_type_cd
 WHERE tdm10_task_id = #{taskId}
   AND tdm10_company_id = #{companyId}

SELECT (
        SELECT COUNT(*)
          FROM tdm21_role_relate_task
               INNER JOIN tdm20_role ON tdm20_role_id = tdm21_role_id
         WHERE tdm21_task_id = #{taskId}
       ) + (
        SELECT COUNT(*)
          FROM tdm35_role_allc_task
               INNER JOIN tdm34_role_allc_detail ON tdm34_role_allc_detail_id = tdm35_role_allc_detail_id
               INNER JOIN apr01_appr             ON (    apr01_appr_id = tdm34_appr_id
                                                     AND COALESCE(apr01_status_cd,'99') IN ('10','20','30') )
         WHERE tdm35_task_id = #{taskId}
       ) + (
        SELECT COUNT(*)
          FROM tdm43_manl
         WHERE tdm43_task_id = #{taskId}
      )

mapper.update:
UPDATE tdm10_task
   SET tdm10_task_class_cd = #{req.taskClassCode}
     , tdm10_task_type_cd  = #{req.taskTypeCode}
     , tdm10_task_nm       = #{req.taskName}
     , tdm10_common_yn     = #{req.commonYn}
     , tdm10_ceo_yn        = #{req.ceoYn}
     , tdm10_start_date    = #{req.startDate}
     , tdm10_end_date      = #{req.endDate}
     , tdm10_upd_nm        = #{updName}
     , tdm10_upd_date      = f_sysdate()
 WHERE tdm10_task_id    = #{req.taskId}
   AND tdm10_company_id = #{companyId}

mapper.delete:
DELETE FROM tdm10_task
 WHERE tdm10_company_id = #{companyId}
   AND tdm10_task_id IN
#{id}
